// The interface in three languages.
//
// English, French and Portuguese - the three the CEO asked for, and the three
// that cover most of the continent V-ENT is built for. Nigerian Pidgin, Yoruba,
// Igbo and Hausa were listed in the picker with nothing behind them, which is
// worse than not offering them.
//
// Keys are dotted and grouped by where the string lives. A missing key falls
// back to English rather than rendering the key itself: an untranslated label
// is a small blemish, `settings.privacy.title` on screen is a bug.

export const LANGUAGES = [
  { code: 'en', label: 'English', native: 'English' },
  { code: 'fr', label: 'French', native: 'Français' },
  { code: 'pt', label: 'Portuguese', native: 'Português' },
];

