    'policy.authoritative': 'This policy is written in English. The French and Portuguese versions are provided so it can be read, and where they differ from the English the English is the version that binds.',
    'policy.back': 'Back to V-ENT',
    'policy.children.heading': '7. Children',
    'policy.children.p0': 'V-ENT is for users aged 13 and over. Wager features, when launched, require users to be 18 or over in line with Nigerian law. We will remove accounts found to be under age.',
    'policy.collect.heading': '2. Information we collect',
    'policy.collect.i0': 'Account information: email, username, full name, country, password hash.',
    'policy.collect.i1': 'Profile information you choose to provide: avatar, banner, bio, social handles, gaming accounts.',
    'policy.collect.i2': 'Wallet activity: top-ups, sends, withdrawals, prize payouts. Card data is handled by Paystack, and we do not store card numbers.',
    'policy.collect.i3': 'Tournament and event activity: registrations, results, brackets, tickets.',
    'policy.collect.i4': 'Device and log data: IP, device, browser, login timestamps, security events.',
    'policy.collect.i5': 'KYC documents when you choose to verify, held in encrypted private storage.',
    'policy.contact.heading': '8. Contact',
    'policy.contactAfter': 'For account-specific actions, use Settings then Danger Zone first. It is the fastest path.',
    'policy.contactIntro': 'Questions or data requests:',
    'policy.rights.heading': '5. Your rights',
    'policy.rights.p0': 'You can edit your profile, export your wallet history, or delete your account from Settings, then Danger Zone. Account deletion is reversible for 14 days, then permanent. Some financial records are retained for tax and audit compliance even after deletion, as required by law.',
    'policy.security.heading': '6. Security',
    'policy.security.p0': 'Passwords are hashed. Sessions are bound to device and IP. KYC documents live in private S3 storage with restricted IAM. Paystack handles card data on PCI-DSS-compliant infrastructure, and V-ENT never sees your card number.',
    'policy.sharing.heading': '4. Sharing',
    'policy.sharing.p0': 'We share data with Paystack for payments, AWS for hosting and storage, AWS SES for transactional email, Cloudflare for DNS and edge, Sentry for error tracking, and PostHog for anonymised analytics. We do not sell your data. We may disclose data when required by law or to protect users from imminent harm.',
    'policy.title': 'Privacy policy',
    'policy.updated': 'Last updated: April 2026 · Vermillion Encore (V-ENT)',
    'policy.use.heading': '3. How we use your data',
    'policy.use.i0': 'To run the platform: host your tournaments, settle wallet transactions, deliver tickets.',
    'policy.use.i1': 'To detect fraud, abuse, and policy violations, including cheat detection, KYC review and payout protection.',
    'policy.use.i2': 'To send you transactional notifications: login alerts, registration confirmations, payouts.',
    'policy.use.i3': 'To send marketing only when you opt in. You can opt out at any time in Settings, then Notifications.',
    'policy.use.i4': 'To comply with Nigerian and African legal requirements where applicable.',
    'policy.who.heading': '1. Who we are',
    'policy.who.p0': 'V-ENT is operated by Vermillion Encore, a company registered in Nigeria. We provide tournaments, events, wallet, marketplace, anime, and community features for African gamers and creators. References to "V-ENT", "we", "our", or "us" mean Vermillion Encore.',
    'register.checkInNote': 'Check-in opens 30 minutes before your first match',
    'register.details': 'Your registration',
    'register.emailOnWay': 'A confirmation with your slot details is on its way to your email',
    'register.success': 'You are registered',
    'scrim.action': 'Action',
    'scrim.format': 'Format',
    'scrim.game': 'Game',
    'scrim.when': 'When',
    'wallet.noMatchingTransactions': 'No transactions match your filters.',
    'wallet.noTransactions': 'No transactions yet. Top up your wallet to get started.',

