    'comingSoon.anime': 'La lecture de mangas, les galeries AMV et les salles de visionnage commun font partie d\'une phase ultérieure. Rien ici n\'est encore actif.',
    'comingSoon.marketplace': 'Les annonces entre joueurs, les offres et le séquestre sont encore en construction.',
    'comingSoon.matchControl': 'Le contrôle des matchs en direct pour la diffusion fait partie du jalon production et n\'est pas encore relié à un stream.',
    'comingSoon.overlay': 'L\'habillage OBS en source navigateur fait partie du jalon production et ne diffuse pas encore de données de match en direct.',
    'comingSoon.production': 'Les habillages de stream, la configuration des scènes et le pipeline OBS font partie du jalon production. Les panneaux sont dessinés mais ne sont pas reliés à un backend en direct.',
    'comingSoon.shop': 'La boutique officielle, avec les produits dérivés, le matériel et les lots de VENT COINS, est encore en construction.',
