    'docs.envelopeBody': 'Succès ou échec, ce sont les mêmes clés au premier niveau et rien d\'autre. Branchez sur code, jamais sur message : le message est écrit pour une personne et peut être reformulé, le code est le contrat.',
    'docs.errInactive': 'Le compte partenaire est suspendu ou pas encore approuvé. Les clés cessent de fonctionner immédiatement, pas à l\'émission suivante. 401.',
    'docs.errMalformed': 'Ce n\'est pas une clé V-ENT. Vérifiez le préfixe vent_pk_ et le point avant le secret. 401.',
    'docs.errNotFound': 'Aucun enregistrement de ce type, ou il n\'est pas public. Un enregistrement privé répond 404 plutôt que 403, car dire qu\'il existe est déjà une divulgation. Aussi TOURNAMENT_NOT_FOUND, TEAM_NOT_FOUND, PLAYER_NOT_FOUND. 404.',
    'docs.failure': 'Échec',
    'docs.limits': 'Limite de débit',
    'docs.limitsBody': '60 requêtes par minute et par clé. Demandez si vous avez besoin de plus, en précisant pourquoi. Les classements et les tableaux terminés changent rarement : une minute de cache ne vous coûte rien et vous garde largement sous la limite.',
    'docs.noWallet': 'Aucune portée ne donne accès à un portefeuille, un solde, une transaction, un versement ou une pièce d\'identité, et il n\'y en aura pas. C\'est inscrit dans le code, pas dans une politique.',
    'docs.paging': 'Pagination',
    'docs.pagingBody': 'Toutes les listes se paginent de la même façon. page commence à 1, page_size vaut 25 par défaut et s\'arrête à 100. Paginez avec has_more plutôt qu\'en comptant : il vient de la même requête que les lignes et ne peut donc pas les contredire.',
    'docs.pkce': 'Créez d\'abord une paire PKCE',
    'docs.pkceBody': 'Gardez le vérificateur dans la session du visiteur, sur votre serveur ; il ne la quitte jamais. N\'envoyez que le défi. Si vous envoyez un défi, c\'est lui qui est vérifié et votre secret client n\'est pas consulté : c\'est pourquoi une application navigateur n\'en a jamais besoin.',
    'docs.readMoneyK': 'Les montants sont des chaînes décimales',
    'docs.readMoneyV': '\\"220000.00\\", pas un nombre. Analysez-le comme un décimal. Une dotation passée par un flottant finira par s\'afficher de travers.',
    'docs.readPrivateK': 'Uniquement les enregistrements publics',
    'docs.readPrivateV': 'Les brouillons, les tournois privés et tout ce qui appartient à un compte suspendu ne sont jamais renvoyés, et aucune portée ne les ouvre.',
    'docs.readSlugK': 'Adressez les enregistrements par slug',
    'docs.readSlugV': 'Toutes les adresses V-ENT visibles utilisent le slug, et un enregistrement renommé garde ses anciennes adresses. C\'est ce qu\'il vous faut dans un lien vers nous.',
    'docs.readTimeK': 'Les heures sont en UTC, ISO 8601',
    'docs.readTimeV': 'Avec le Z à la fin. Convertissez pour vos propres lecteurs ; ne supposez pas Lagos.',
    'docs.reading': 'Quatre choses à savoir avant de construire',
    'docs.revoke': 'Toute personne connectée avec V-ENT peut retirer la connexion depuis son compte, et les jetons existants cessent alors de fonctionner. Traitez BAD_TOKEN en relançant le parcours, pas en conservant une session morte.',
    'docs.subK': 'Identifiez le compte par sub',
    'docs.subV': 'Pas par le nom d\'utilisateur. Une personne peut le changer ; sub reste stable toute la vie du compte et c\'est le seul champ ici que vous pouvez utiliser comme clé primaire.',
    'docs.success': 'Succès',
