    'ui.unexpected.error.occurred.event.30db': 'Ocorreu um erro inesperado no criador de eventos. O seu rascunho está guardado localmente.',
    'ui.unexpected.error.occurred.while.2dd0': 'Ocorreu um erro inesperado ao carregar os seus torneios.',
    'ui.unexpected.error.occurred.while.38ba': 'Ocorreu um erro inesperado ao carregar este torneio.',
    'ui.unexpected.error.occurred.while.3e71': 'Ocorreu um erro inesperado ao carregar os eventos.',
