    'admin.chart.coins': 'VENT COINS emitidos por carregamentos e prémios',
    'admin.chart.registrations': 'Inscrições de jogadores e equipas',
    'admin.chart.signups': 'Novos registos por dia',
    'comingSoon.anime': 'A leitura de manga, as galerias de AMV e as salas de visionamento em conjunto fazem parte de uma fase posterior. Nada aqui está ativo ainda.',
    'comingSoon.marketplace': 'Os anúncios entre jogadores, as ofertas e o depósito em garantia ainda estão a ser construídos.',
    'comingSoon.matchControl': 'O controlo de jogos em direto para transmissões faz parte do marco de produção e ainda não está ligado a uma stream.',
    'comingSoon.overlay': 'O overlay OBS por fonte de navegador faz parte do marco de produção e ainda não serve dados de jogo em direto.',
    'comingSoon.production': 'Os overlays de stream, a configuração de cenas e o pipeline OBS fazem parte do marco de produção. Os painéis estão desenhados mas não estão ligados a um backend em direto.',
    'comingSoon.shop': 'A loja oficial, com merchandising, equipamento e pacotes de VENT COINS, ainda está a ser construída.',
    'comingSoon.wager': 'As apostas em jogos precisam de análise jurídica antes de sair, e são o último módulo do roteiro.',
