    'landing.alt.manageEvents': 'O ecrã de eventos do organizador: uma tabela de eventos com o tipo, o jogo, o local, as datas e o estado, e um botão para criar um novo',
    'landing.alt.shirt': 'Uma t-shirt V-ENT, um dos artigos da loja',
