    'tip.adminBanner': 'Uma mensagem mostrada no topo do site a toda a gente. Use-a só para paragens previstas e incidentes reais.',
    'tip.adminBannerEnabled': 'Mostra o banner a todos os visitantes, com sessão ou sem ela. Desligado é o estado normal.',
    'tip.adminBannerTitle': 'A linha que as pessoas leem primeiro. Fique pelo facto: o que está a acontecer, não o quanto se lamenta.',
    'tip.adminBannerType': 'A cor do banner, que é o quão urgente parece. Use a mais forte só para algo que esteja mesmo avariado.',
    'tip.adminDailyCap': 'O máximo que uma conta pode carregar num dia, em nairas. Um limite antifraude e não comercial.',
    'tip.adminDqTeam': 'A equipa que está a ser retirada do torneio. É informada, e os jogos que lhe restavam ficam perdidos por desistência.',
    'tip.adminFeatureFlags': 'Liga ou desliga um módulo para toda a gente de uma vez. Um módulo desligado fica oculto, e nada lá dentro é apagado.',
    'tip.adminListingFee': 'A parte retirada numa venda do marketplace, em percentagem.',
