    'docs.errNotFound': 'Não existe tal registo, ou não é público. Um registo privado responde 404 em vez de 403, porque dizer que existe já é uma divulgação. Também TOURNAMENT_NOT_FOUND, TEAM_NOT_FOUND, PLAYER_NOT_FOUND. 404.',
    'docs.failure': 'Falha',
    'docs.limits': 'Limite de pedidos',
    'docs.limitsBody': '60 pedidos por minuto por chave. Peça se precisar de mais, dizendo para quê. As classificações e os quadros terminados mudam raramente, por isso um minuto de cache não lhe custa nada e mantém-no bem dentro do limite.',
    'docs.noWallet': 'Não existe nenhum âmbito que leia uma carteira, um saldo, uma transação, um pagamento ou um documento de identidade, e não passará a existir. Está escrito no código, não numa política.',
    'docs.paging': 'Paginação',
    'docs.pagingBody': 'Todas as listas paginam da mesma forma. page começa em 1, page_size é 25 por omissão e para nos 100. Pagine com has_more em vez de contar: vem da mesma consulta que as linhas, por isso não as pode contradizer.',
    'docs.pkce': 'Crie primeiro um par PKCE',
    'docs.pkceBody': 'Guarde o verificador na sessão do visitante, no seu servidor; nunca sai dela. Envie apenas o desafio. Se enviar um desafio, é esse que é verificado e o seu segredo de cliente não é consultado, razão pela qual uma aplicação de navegador nunca precisa de um.',
    'docs.readMoneyK': 'O dinheiro é uma cadeia decimal',
