    'docs.readSlugK': 'Enderece os registos por slug',
    'docs.readSlugV': 'Todos os endereços V-ENT que uma pessoa vê usam o slug, e um registo renomeado mantém os endereços antigos a funcionar. É o que quer num link de volta para nós.',
